  "initialQuestion": {
    "adoptedEpisodeRefs": [],
    "content": "请检查并修复以下Java代码，确保在多个服务实例并发扣减同一商品库存时不会出现库存为负数的情况，并且同一业务订单（orderId）的重复调用不会导致重复扣减。请直接修改代码并说明你的修改点。",
    "decisionSummary": "JD明确关注多实例并发一致性，因此首题选择CODE_REPAIR，直接验证候选人对并发原子更新与幂等控制的实现能力。",
    "nextProbeIntent": "观察候选人是否采用条件原子更新或悲观锁并验证影响行数，以及是否主动引入基于orderId的幂等机制。",
    "questionType": "CODE_REPAIR",
    "targetOrder": 0,
    "codeTask": {
      "assumptions": [
        "库存数据持久化在关系数据库中，所有服务实例共享同一个数据库",
        "inventory表的stock字段为整数，productId为主键",
        "多个服务实例可能同时处理同一商品的扣减请求",
        "客户端可能因网络超时重试同一扣减请求，orderId用于标识业务唯一性",
        "事务隔离级别为数据库默认（通常为READ_COMMITTED）"
      ],
      "initialCode": "import jakarta.persistence.*;\nimport org.springframework.data.jpa.repository.*;\nimport org.springframework.stereotype.*;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Entity\npublic class Inventory {\n    @Id\n    private Long productId;\n    private int stock;\n    public Long getProductId() { return productId; }\n    public void setProductId(Long productId) { this.productId = productId; }\n    public int getStock() { return stock; }\n    public void setStock(int stock) { this.stock = stock; }\n}\n\n@Repository\npublic interface InventoryRepository extends JpaRepository<Inventory, Long> {\n    @Modifying\n    @Query(\"UPDATE Inventory i SET i.stock = i.stock - :quantity WHERE i.id = :productId\")\n    int decrementStock(@Param(\"productId\") Long productId, @Param(\"quantity\") int quantity);\n}\n\n@Service\npublic class InventoryService {\n    private final InventoryRepository inventoryRepository;\n\n    public InventoryService(InventoryRepository inventoryRepository) {\n        this.inventoryRepository = inventoryRepository;\n    }\n\n    @Transactional\n    public void deduct(Long productId, Long orderId, int quantity) {\n        Inventory inventory = inventoryRepository.findById(productId)\n                .orElseThrow(() -> new IllegalArgumentException(\"Product not found\"));\n        if (inventory.getStock() < quantity) {\n            throw new IllegalStateException(\"Insufficient stock\");\n        }\n        int updated = inventoryRepository.decrementStock(productId, quantity);\n        if (updated == 0) {\n            // 正常情况不会进入，除非商品被并发删除\n        }\n    }\n}",
      "requirements": [
        "扣减操作必须保证库存永远不会减为负数",
        "同一orderId的扣减请求重复调用时，只能成功扣减一次，后续调用视为幂等成功",
        "在多个服务实例并发扣减同一商品时，最终的库存数量必须正确反映所有成功扣减的总和"
      ],
      "reviewGuide": {
        "checks": [
          {
            "id": "atomic-conditional-update",
            "defect": "先查询库存再执行无条件递减，存在check-then-act竞态，并发下会导致库存被扣成负数",
            "trigger": "两个并发扣减请求读取到相同的初始库存，都通过充足性检查，随后都执行无条件递减，总扣减量超过实际库存",
            "acceptance": "扣减必须合并为单个原子条件更新（如 UPDATE ... SET stock = stock - :q WHERE id = :id AND stock >= :q），或在事务内使用悲观锁并重新检查，保证库存永不为负"
          },
          {
            "id": "idempotency",
            "defect": "orderId参数未被使用，重复请求会导致同一订单多次扣减库存",
            "trigger": "客户端因网络超时重试同一扣减请求，服务端再次执行扣减逻辑",
            "acceptance": "通过唯一业务键（如订单号）去重，例如引入幂等表或唯一约束，已处理过的orderId直接返回成功，不再重复扣减"
          },
          {
            "id": "zero-rows-validation",
            "defect": "未验证递减更新的影响行数，当条件更新未匹配任何行时静默失败，可能导致不一致状态",
            "trigger": "采用条件更新后，并发场景下库存恰好不足或商品不存在，更新影响行数为0",
            "acceptance": "当条件更新影响行数为0时，应抛出明确异常或触发事务回滚，避免调用方误认为扣减成功"
          }
        ]
      }
    },
    "codeTaskTurnIndex": null
  }
}
